import type { ICtx } from "@threenative/core";
import {
  CharacterBody3D,
  CollisionShape3D,
  type IPhysicsContext,
  NavigationAgent3D,
  type NavigationRegion3D,
} from "@threenative/physics";
import { NavigationAgent3D as NavigationAgent3DNav } from "@threenative/physics/navigation";
import { type Group, Vector3 } from "three";
import { attachToBone } from "@threenative/core";
import { createEnemyVisual, createRifleVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const MOVE_SPEED = 2.8;
const PATROL_STOP_DISTANCE = 0.5;
const CHASE_STOP_DISTANCE = 1.2;
const SIGHT_RANGE = 12;
const FIRE_RATE = 0.4;

export class Enemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "enemy"];
  health: number;
  alive = true;
  seeingPlayer = false;
  #fireTimer = 0;
  #navigationAgent: NavigationAgent3D | null = null;
  #targetPosition = new Vector3();
  #currentPatrolIndex = 0;
  #patrolPoints: Vector3[] = [];
  #onFire: (origin: Vector3) => void;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createEnemyVisual>[0],
    position: Vector3,
    navigation: NavigationRegion3D | null,
    patrolPoints: Vector3[],
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3) => void;
    } = {},
  ) {
    this.health = options.health ?? 60;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#patrolPoints = patrolPoints.length > 0 ? patrolPoints : [position.clone()];
    this.#targetPosition.copy(this.#patrolPoints[0] ?? position);

    this.mesh = createEnemyVisual(materials);
    this.mesh.position.copy(position);
    ctx.add(this.mesh);

    const rifle = createRifleVisual(materials);
    attachToBone(this.mesh, "RightHand", rifle);

    this.body = new CharacterBody3D({
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.35, 0.38),
    });

    if (navigation !== null) {
      this.#navigationAgent = new NavigationAgent3DNav({
        navigation,
        object: this.mesh,
      });
    }
  }

  update(ctx: GameCtx, dt: number, playerPosition: Vector3): void {
    if (!this.alive) return;

    const distToPlayer = this.mesh.position.distanceTo(playerPosition);
    this.seeingPlayer = distToPlayer < SIGHT_RANGE;

    if (this.seeingPlayer) {
      this.#targetPosition.copy(playerPosition);
    } else {
      this.#updatePatrolTarget();
    }

    this.#updateMovement();
    this.#updateFiring(dt, playerPosition, distToPlayer);
    this.body.moveAndSlide(dt);
  }

  #updatePatrolTarget(): void {
    const distToPatrol = this.mesh.position.distanceTo(this.#targetPosition);
    if (distToPatrol < PATROL_STOP_DISTANCE) {
      this.#currentPatrolIndex = (this.#currentPatrolIndex + 1) % this.#patrolPoints.length;
