const spawnWave = (wave: number): void => {
  const target = registerTarget(`wave.target.${wave}`, WAVE_POSITION.clone(), {
    health: 35,
    wave,
  });
  waveTargets.push({ id: `wave.target.${wave}`, target });

  const enemyCount = Math.min(1 + wave, 4);
  for (let i = 0; i < enemyCount; i++) {
    const angle = (i / enemyCount) * Math.PI * 2;
    const distance = 3 + wave * 0.5;
    const enemyPos = new Vector3(
      Math.cos(angle) * distance,
      0.85,
      -2 + Math.sin(angle) * distance,
    );
    const enemy = registerEnemy(`wave.enemy.${wave}.${i}`, enemyPos, {
      health: 35 + wave * 10,
    });
    enemies.push({ id: `wave.enemy.${wave}.${i}`, value: enemy });
  }

  ctx.state.set({ targetsRemaining: 1 + enemyCount, wave });
  emitPlaytestEvent({ entity: "wave", name: "started", wave });
};
waveDirector.start(spawnWave);
rig.snap(player.mesh.position);

